    #[test]
    #[should_panic(expected = "cannot Ok/Err-match a fetch/http/browser result")]
    fn codegen_fail_loud_fetch_result_match() {
        // Regression: Ok/Err-matching an inline fetch() Response silently
        // skipped both arms — native read the opaque handle as a TallowResult
        // and exited 0 with no output. The guard must refuse (Err → panic in
        // compile_to_ir) so `tallow run` falls back to the interpreter.
        compile_to_ir(
            r#"
            fn main() {
                let r = fetch("https://example.com") match {
                    Ok(resp) -> resp.text()
                    Err(e) -> { print("err: {e}") }
                }
            }
        "#,
        );
    }

    #[test]
    #[should_panic(expected = "cannot Ok/Err-match a fetch/http/browser result")]
    fn codegen_fail_loud_browser_result_match() {
        // Browser.launch() returns a bare opaque handle, not a Result — an
        // Ok/Err match on it must refuse, not silently compile to nothing.
        compile_to_ir(
            r#"
            fn main() {
                let b = Browser.launch(true) match {
                    Ok(br) -> br
                    Err(e) -> { print("err: {e}") }
                }
            }
        "#,
        );
    }

    #[test]
    fn codegen_genuine_result_match_still_compiles() {
        // A genuine user Result must NOT be refused by the FFI-handle guard.
        let ok_genuine = compile_to_ir(
            r#"
            fn safe_div(a: i32, b: i32) -> Result<i32> {
                if b == 0 { return Err("division by zero") }
                Ok(a / b)
            }
            fn main() {
                let r = safe_div(10, 2)
                let v = r match {
                    Ok(x) -> x
                    Err(_) -> 0
                }
                print(v)
            }
        "#,
        );
        assert!(
            !ok_genuine.contains("cannot Ok/Err-match"),
            "genuine Result must not be refused (got: {ok_genuine})"
        );
    }

    #[test]
    fn codegen_result_match_err_payload_bound_as_string() {
        // Bug 3 regression: `Err(e) match { Err(e) -> ... }` bound the Err
        // payload as a raw i64 alloca, so a string error printed as a pointer
        // (e.g. `err 189115555974016`) instead of the message. The Err payload
        // is an error-message string (same convention as the `if let` handler):
        // the match emitter must inttoptr it back and bind the var as I8Ptr so
        // interpolation / string ops work. Assert the IR carries the ptr alloca +
        // inttoptr for an Err arm, and that an Ok-int arm still binds as i64.
        let ir = compile_to_ir(
            r#"
            fn safe_div(a: i32, b: i32) -> Result<int> {
                if b == 0 { return Err("division by zero") }
                Ok(a / b)
            }
            fn main() {
                let r = safe_div(10, 0)
                let v = r match {
                    Ok(x) -> x
                    Err(e) -> { print("err {e}"); 0 }
                }
                print(v)
            }
        "#,
        );
        assert!(
            ir.contains("inttoptr i64"),
            "Err-arm payload must be inttoptr'd back to a string pointer"
        );
        assert!(
            ir.contains("alloca ptr"),
            "Err-arm payload must be bound into a ptr alloca (I8Ptr string)"
        );
        assert!(
            ir.contains("alloca i64"),
            "Ok-int arm payload must still bind into an i64 alloca"
        );
    }

