    #[test]
    fn codegen_multiple_functions_call_chain() {
        let ir = compile_to_ir(
            r#"
            fn double(x: i64) -> i64 { x * 2 }
            fn triple(x: i64) -> i64 { x * 3 }
            fn main() {
                let a = double(5)
                let b = triple(a)
                print(b)
            }
        "#,
        );
        assert!(ir.contains("@tallow.double"));
        assert!(ir.contains("@tallow.triple"));
        assert!(ir.contains("call i64 @tallow.double"));
        assert!(ir.contains("call i64 @tallow.triple"));
    }

    #[test]
    fn codegen_nested_if_else_chain() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let x = 42
                if x > 100 {
                    print("big")
                } else if x > 50 {
                    print("medium")
                } else {
                    print("small")
                }
            }
        "#,
        );
        assert!(ir.contains("icmp sgt i64"));
        assert!(ir.contains("br i1"));
        // Should have multiple branch labels
        let label_count = ir.matches("br i1").count();
        assert!(
            label_count >= 2,
            "should have at least 2 conditional branches"
        );
    }

