    // ── Instance Method Dispatch Tests ──────────────────────────────────

    #[test]
    fn codegen_struct_instance_method_no_args() {
        // Instance method with only self param: p.url()
        let ir = compile_to_ir(
            r#"
            struct Config {
                host: String,
                port: u16
            }
            impl Config {
                fn url(self) -> String {
                    "http://localhost"
                }
            }
            fn main() {
                let cfg = Config { host: "localhost", port: 8080 }
                let u = cfg.url()
                print(u)
            }
        "#,
        );
        // Should define Config::url method
        assert!(ir.contains("@\"tallow.Config::url\""));
        // Should call it with the struct pointer as self
        assert!(ir.contains("call ptr @\"tallow.Config::url\"(ptr"));
    }

    #[test]
    fn codegen_struct_instance_method_with_args() {
        // Instance method with self + extra param: p.with_port(9090)
        let ir = compile_to_ir(
            r#"
            struct Server {
                port: u16
            }
            impl Server {
                fn set_port(self, new_port: u16) -> i64 {
                    42
                }
            }
            fn main() {
                let s = Server { port: 8080 }
                let r = s.set_port(9090)
                print(r)
            }
        "#,
        );
        // Should define Server::set_port
        assert!(ir.contains("@\"tallow.Server::set_port\""));
        // Call with self ptr + the i32 arg
        assert!(ir.contains("call i64 @\"tallow.Server::set_port\"(ptr"));
    }

    #[test]
    fn codegen_struct_static_and_instance_methods() {
        // Both static and instance methods on same struct
        let ir = compile_to_ir(
            r#"
            struct Counter {
                value: i64
            }
            impl Counter {
                fn new() -> i64 {
                    0
                }
                fn get(self) -> i64 {
                    1
                }
            }
            fn main() {
                let n = Counter.new()
                let c = Counter { value: 0 }
                let v = c.get()
                print(v)
            }
        "#,
        );
        // Static method call (no self ptr)
        assert!(ir.contains("call i64 @\"tallow.Counter::new\"()"));
        // Instance method call (with self ptr)
        assert!(ir.contains("call i64 @\"tallow.Counter::get\"(ptr"));
    }

    #[test]
    fn codegen_struct_method_self_type_is_ptr() {
        // Verify that Self type maps to ptr in function signature
        let ir = compile_to_ir(
            r#"
            struct Point {
                x: i64,
                y: i64
            }
            impl Point {
                fn magnitude(self) -> i64 {
                    0
                }
            }
            fn main() {
                let p = Point { x: 3, y: 4 }
                let m = p.magnitude()
                print(m)
            }
        "#,
        );
        // The self param should be ptr type in the function definition
        assert!(ir.contains("define i64 @\"tallow.Point::magnitude\"(ptr %param.self) #0"));
    }

    #[test]
    fn codegen_multiple_struct_instance_methods() {
        // Multiple methods on same struct
        let ir = compile_to_ir(
            r#"
            struct Rect {
                w: i64,
                h: i64
            }
            impl Rect {
                fn area(self) -> i64 {
                    1
                }
                fn perimeter(self) -> i64 {
                    2
                }
            }
            fn main() {
                let r = Rect { w: 10, h: 5 }
                let a = r.area()
                let p = r.perimeter()
                print(a)
                print(p)
            }
        "#,
        );
        assert!(ir.contains("call i64 @\"tallow.Rect::area\"(ptr"));
        assert!(ir.contains("call i64 @\"tallow.Rect::perimeter\"(ptr"));
    }

