    // ── Self field access in impl methods ───────────────────────────

    #[test]
    fn codegen_self_field_access_in_method() {
        // self.x should emit GEP into the struct with proper field index
        let ir = compile_to_ir(
            r#"
            struct Point { x: i64, y: i64 }
            impl Point {
                fn get_x(self) -> i64 { self.x }
            }
            fn main() {
                let p = Point { x: 42, y: 99 }
                let x = p.get_x()
                print(x)
            }
        "#,
        );
        // Method should have self param as ptr
        assert!(ir.contains("define i64 @\"tallow.Point::get_x\"(ptr %param.self) #0"));
        // Should GEP into struct to access field x (index 0)
        assert!(ir.contains("getelementptr inbounds %struct.Point"));
        // Should load the field
        assert!(ir.contains("load i64"));
    }

    #[test]
    fn codegen_self_field_access_second_field() {
        // Access the second field: self.y should use GEP index 1
        let ir = compile_to_ir(
            r#"
            struct Pair { a: i64, b: i64 }
            impl Pair {
                fn get_b(self) -> i64 { self.b }
            }
            fn main() {
                let p = Pair { a: 1, b: 2 }
                let v = p.get_b()
                print(v)
            }
        "#,
        );
        assert!(ir.contains("define i64 @\"tallow.Pair::get_b\"(ptr %param.self) #0"));
        // GEP with i32 1 to access second field
        assert!(ir.contains("i32 0, i32 1"));
    }

    #[test]
    fn codegen_self_field_access_arithmetic() {
        // self.x + self.y should emit two GEPs and an add
        let ir = compile_to_ir(
            r#"
            struct Vec2 { x: i64, y: i64 }
            impl Vec2 {
                fn sum(self) -> i64 { self.x + self.y }
            }
            fn main() {
                let v = Vec2 { x: 10, y: 20 }
                let total = v.sum()
                print(total)
            }
        "#,
        );
        assert!(ir.contains("define i64 @\"tallow.Vec2::sum\"(ptr %param.self) #0"));
        // Should have GEP for both x and y, then add
        assert!(ir.contains("add i64"));
    }

