    // ── Result/Option codegen tests ─────────────────────────────────

    #[test]
    fn codegen_ok_constructor() {
        let ir = compile_to_ir(
            r#"
            fn main() { let r = Ok(42) }
        "#,
        );
        assert!(
            ir.contains("TallowResult"),
            "should reference TallowResult struct: {ir}"
        );
        assert!(
            ir.contains("getelementptr %struct.TallowResult"),
            "should GEP into result"
        );
        assert!(ir.contains("store i64 0"), "should store tag=0 for Ok");
    }

    #[test]
    fn codegen_err_constructor() {
        let ir = compile_to_ir(
            r#"
            fn main() { let r = Err("oops") }
        "#,
        );
        assert!(
            ir.contains("TallowResult"),
            "should reference TallowResult struct"
        );
        assert!(ir.contains("store i64 1"), "should store tag=1 for Err");
    }

    #[test]
    fn codegen_ok_and_err_both_use_tallow_result() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let a = Ok(10)
                let b = Err("bad")
            }
        "#,
        );
        // Both should create TallowResult structs via malloc (heap-allocated, 24 bytes for {tag, value, value_type})
        let count = ir.matches("call ptr @malloc(i64 24)").count();
        assert!(
            count >= 2,
            "should have at least 2 TallowResult mallocs, got {count}"
        );
    }

    #[test]
