    // ── B4: print of composites (stdout/print parity) ──────────────────────

    #[test]
    fn b4_print_array_routes_to_display_renderer() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let a = [1, 2, 3]
                print(a)
            }
        "#,
        );
        assert!(
            ir.contains("call ptr @tallow_display_array(ptr "),
            "print(<array>) must route to the runtime display renderer: {ir}"
        );
        assert!(ir.contains("declare ptr @tallow_display_array(ptr, i32)"));
    }

    #[test]
    fn b4_print_map_passes_string_key_flag() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let m = {"k": 1, "j": "v"}
                print(m)
            }
        "#,
        );
        assert!(
            ir.contains("call ptr @tallow_display_map(ptr ") && ir.contains(", i32 1)"),
            "print(<string-keyed map>) must pass the string-key flag: {ir}"
        );
    }

    #[test]
    fn b4_print_map_value_uses_tag_dispatch() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let m = {"name": "ada"}
                print(m["name"])
            }
        "#,
        );
        // The tagged dispatch renders the string payload; the old path printed
        // the payload bits through the integer printf slot.
        assert!(ir.contains("tag.done"), "tagged dispatch missing: {ir}");
    }

    #[test]
    fn b4_print_mixed_array_fails_loud() {
        // The native array layout has no per-element tags: a mixed-type array
        // print must refuse the native build (tallow run then falls back to the
        // correct interpreter) instead of printing decoded garbage.
        let (tokens, errors) = lexer::tokenize(
            r#"
            fn main() {
                print([1, "two"])
            }
        "#,
        );
        assert!(errors.is_empty(), "lex errors: {errors:?}");
        let program = parser::Parser::parse(tokens).expect("parse error");
        let (env, _) = TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        let err = cg
            .emit_module()
            .expect_err("mixed-type array print must fail loud");
        assert!(err.contains("mixed-type array"), "{err}");
    }

