    // ── PHI node completeness tests ─────────────────────────────────────────

    #[test]
    fn codegen_int_switch_default_fallthrough() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let x = 42
                let r = match x {
                    1 -> 10
                    2 -> 20
                    _ -> 99
                }
                print(r)
            }
        "#,
        );
        assert!(ir.contains("switch i64"));
        assert!(ir.contains("phi i64"));
    }

    #[test]
    fn codegen_result_match_string_payload_binds_ptr() {
        // A `Result<String>` arm must bind the payload as a string, and the inline
        // chained form must not trip the opaque-handle guard: `page.title()`
        // returns a genuine Result, not a browser handle.
        let ir = compile_to_ir(
            r#"
            fn main() {
                let browser = Browser.launch(true)
                let page = browser.new_page()
                let m = page.title() match {
                    Ok(v) -> v
                    Err(e) -> "E"
                }
                print(m)
            }
        "#,
        );
        assert!(
            ir.contains("inttoptr i64"),
            "string Ok payload must inttoptr back to a string pointer"
        );
        assert!(
            ir.contains("alloca ptr"),
            "string Ok payload must bind into a ptr alloca"
        );
        assert!(
            !ir.contains("cannot Ok/Err-match"),
            "an inline Result match on a Result-returning method must not be refused"
        );
    }

    #[test]
    fn codegen_result_match_int_payload_keeps_i64() {
        // The long-standing convention, pinned: an unknown/user `Result<int>`
        // payload still binds as i64 (see codegen_result_match_err_*).
        let ir = compile_to_ir(
            r#"
            fn safe_div(a: i32, b: i32) -> Result<int> {
                if b == 0 { return Err("zero") }
                Ok(a / b)
            }
            fn main() {
                let r = safe_div(4, 2)
                let v = r match {
                    Ok(x) -> x
                    Err(e) -> 0
                }
                print(v)
            }
        "#,
        );
        assert!(
            ir.contains("alloca i64"),
            "a user Result<int> must keep the i64 binding shape"
        );
    }

    #[test]
    fn codegen_query_selector_payload_is_tagged_handle() {
        // `query_selector` is declared Result<Element>: its payload must be tagged
        // value_type 4 (handle), never 2 (string) — tagging it 2 would print the
        // raw pointer address as if it were text.
        let ir = compile_to_ir(
            r#"
            fn main() {
                let browser = Browser.launch(true)
                let page = browser.new_page()
                let el = page.query_selector("h1")
                let t = el.text()
                print(t)
            }
        "#,
        );
        assert!(
            ir.contains("store i64 4"),
            "a handle payload must be tagged value_type 4"
        );
    }

    #[test]
    fn codegen_result_match_err_phi() {
        let ir = compile_to_ir(
            r#"
            fn divide(a: i64, b: i64) -> Result<i64> {
                if b == 0 { bail "div zero" }
                Ok(a / b)
            }
            fn main() {
                let r = divide(10, 0) match {
                    Ok(v) -> v
                    Err(msg) -> -1
                }
                print(r)
            }
        "#,
        );
        assert!(ir.contains("result.merge"));
        assert!(ir.contains("phi i64"));
    }

