    // ── Bail generates Result Err ───────────────────────────────────────────

    #[test]
    fn codegen_bail_generates_err() {
        let ir = compile_to_ir(
            r#"
            fn check(n: i64) -> Result<i64> {
                if n < 0 { bail "negative" }
                Ok(n)
            }
            fn main() {
                let r = check(0 - 1)
                print(r)
            }
        "#,
        );
        // bail desugars to return Err(...)
        assert!(ir.contains("store i64 1"), "should store tag=1 for Err");
    }

