    /// Cycle-02/08 §3(a) Option A: `@legal` functions emit an audit entry call
    /// at entry (default-on); unannotated functions emit none.
    #[test]
    fn codegen_legal_audit_emission() {
        let ir = compile_to_ir(
            r#"
            @legal(basis: .public_data, purpose: "unit check", retain_for: "7.days")
            fn annotated(a: i64) -> i64 { a + 1 }

            fn unannotated(b: i64) -> i64 { b + 2 }

            fn main() {
                print(annotated(1))
                print(unannotated(2))
            }
        "#,
        );

        assert!(
            ir.contains("call i32 @tallow_audit_log(ptr"),
            "annotated fn must emit an audit call \
             (cycle-02/08 Option A default-on):\n{ir}"
        );
        assert_eq!(
            ir.matches("call i32 @tallow_audit_log(ptr").count(),
            1,
            "exactly one audit call site expected (the @legal fn only)"
        );
        assert!(
            ir.contains(r#"{\22legal_basis\22:\22public_data\22,\22purpose\22:\22unit check\22,\22retain_for\22:\227.days\22}"#),
            "the details JSON (basis/purpose/retain_for) must be interned:\n{ir}"
        );

        // The `@legal`-annotated function's own body carries the call.
        let annotated_start = ir
            .find("define i64 @tallow.annotated(")
            .expect("annotated fn emitted");
        let annotated_body = &ir[annotated_start..];
        let body_end = annotated_body.find("\n}\n").expect("fn body end");
        assert!(
            annotated_body[..body_end].contains("call i32 @tallow_audit_log(ptr"),
            "the audit call must sit inside @annotated's body:\n{}",
            &annotated_body[..body_end]
        );
    }

