    #[test]
    fn codegen_stdlib_math_functions() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                print(math.sin(0.0))
                print(math.cos(0.0))
                print(math.tan(0.0))
                print(math.sqrt(4.0))
                print(math.pow(2.0, 3.0))
                print(math.abs(-5.0))
                print(math.floor(3.7))
                print(math.ceil(3.2))
                print(math.round(3.5))
                print(math.log2(8.0))
                print(math.log10(1000.0))
                print(math.min(3.0, 7.0))
                print(math.max(3.0, 7.0))
            }
        "#,
        );
        assert!(ir.contains("call double @sin(double"), "should call sin");
        assert!(ir.contains("call double @cos(double"), "should call cos");
        assert!(ir.contains("call double @tan(double"), "should call tan");
        assert!(ir.contains("call double @pow(double"), "should call pow");
        assert!(ir.contains("call double @log2(double"), "should call log2");
        assert!(
            ir.contains("call double @log10(double"),
            "should call log10"
        );
        assert!(
            ir.contains("call double @llvm.fabs.f64(double"),
            "should call fabs for abs"
        );
        assert!(
            ir.contains("call double @llvm.floor.f64(double"),
            "should call floor"
        );
        assert!(
            ir.contains("call double @llvm.ceil.f64(double"),
            "should call ceil"
        );
        assert!(
            ir.contains("call double @llvm.round.f64(double"),
            "should call round"
        );
        assert!(
            ir.contains("call double @llvm.sqrt.f64(double"),
            "should call sqrt"
        );
        assert!(ir.contains("fcmp olt double"), "should have min comparison");
        assert!(ir.contains("fcmp ogt double"), "should have max comparison");
    }

