    #[test]
    fn codegen_stdlib_time_now() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let t = time.now()
                print(t)
            }
        "#,
        );
        // B4 parity: `time.now` must be MILLIS, matching the interpreter
        // (src/interp.rs "now"). It previously lowered to `@time(NULL)`
        // (seconds), which silently disagreed with `time.parse_iso` by 1000x.
        assert!(
            ir.contains("call i64 @tallow_time_now_ms()"),
            "time.now must lower to the runtime millis helper"
        );
    }

    #[test]
    fn codegen_stdlib_time_parse_iso() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let t = time.parse_iso("2026-10-12T00:00:00Z")
                print(t)
            }
        "#,
        );
        assert!(
            ir.contains("call i64 @tallow_time_parse_iso(ptr"),
            "time.parse_iso must lower to the runtime parser"
        );
        // The failure sentinel must be checked, not ignored — a malformed
        // timestamp has to fail loudly rather than return the epoch.
        assert!(
            ir.contains("icmp eq i64 %") && ir.contains("-9223372036854775808"),
            "parse_iso must branch on the TIME_PARSE_FAILED sentinel"
        );
    }

