    #[test]
    fn codegen_stdlib_fs_append_and_rmdir_lower_fail_closed() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                fs.append_file("/tmp/tallow-probe.txt", "x")
                fs.remove_dir_all("/tmp/tallow-probe-dir")
            }
        "#,
        );
        assert!(
            ir.contains("call i32 @tallow_fs_append_file(ptr"),
            "fs.append_file must lower to the runtime helper"
        );
        assert!(
            ir.contains("call i32 @tallow_fs_remove_dir_all(ptr"),
            "fs.remove_dir_all must lower to the runtime helper"
        );
        // Both must check the status: a negative code exits non-zero with the
        // runtime's message rather than reporting a silent success.
        assert!(
            ir.matches("icmp slt i32 %").count() >= 2,
            "both fs calls must branch on the negative-status check"
        );
    }

