    #[test]
    fn reproducible_struct_emission_deterministic() {
        // Two structs defined — emission order should be sorted by name
        let source = r#"
struct Beta { x: i32 }
struct Alpha { y: i32 }
fn main() {
    let a = Alpha { y: 1 }
    let b = Beta { x: 2 }
}
"#;
        let ir = compile_to_ir(source);
        // Alpha should appear before Beta in the IR (sorted)
        let alpha_pos = ir.find("%struct.Alpha").expect("Alpha struct not in IR");
        let beta_pos = ir.find("%struct.Beta").expect("Beta struct not in IR");
        assert!(
            alpha_pos < beta_pos,
            "Struct types should be emitted in sorted order (Alpha before Beta)"
        );
    }

    #[test]
    fn reproducible_fn_signatures_deterministic() {
        // Multiple functions — their forward declarations should be deterministic
        let source = r#"
fn zebra() -> i32 { 1 }
fn alpha() -> i32 { 2 }
fn main() {
    let a = alpha()
    let z = zebra()
}
"#;
        // Compile twice and compare — should produce identical IR
        let ir1 = compile_to_ir(source);
        let ir2 = compile_to_ir(source);
        assert_eq!(
            ir1, ir2,
            "Two compilations of the same source should produce identical IR"
        );
    }

