    // ── Async Runtime Stub Tests ────────────────────────────────────────────

    #[test]
    fn async_runtime_stub_generated() {
        // When compiling an async program, the stub C file should be generated
        let source = r#"
            async fn work() -> i64 { 42 }
            fn main() {
                let h = work()
            }
        "#;
        let (tokens, errors) = lexer::tokenize(source);
        assert!(errors.is_empty());
        let program = parser::Parser::parse(tokens).expect("parse error");
        let (env, _) = TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        let ir = cg.emit_module().expect("codegen error");

        // has_async should be true
        assert!(cg.has_async, "has_async flag should be set");

        // Generate the stub content and verify it's valid C
        let stub = CodeGen::async_stub_source();
        assert!(
            stub.contains("tallow_async_spawn"),
            "stub should define tallow_async_spawn"
        );
        assert!(
            stub.contains("tallow_async_await"),
            "stub should define tallow_async_await"
        );
        assert!(
            stub.contains("tallow_async_runtime_init"),
            "stub should define tallow_async_runtime_init"
        );
        assert!(
            stub.contains("tallow_async_runtime_shutdown"),
            "stub should define tallow_async_runtime_shutdown"
        );
    }

    #[test]
    fn async_runtime_interp_sequential() {
        // Interpreter should handle async fn by running sequentially (existing behavior)
        use crate::interp::Interpreter;

        let source = r#"
            async fn get_value() -> i64 {
                42
            }
            fn main() {
                let result = get_value().await
                print(result)
            }
        "#;
        let (tokens, errors) = lexer::tokenize(source);
        assert!(errors.is_empty());
        let program = parser::Parser::parse(tokens).expect("parse error");
        let mut interp = Interpreter::new();
        let output = interp.run_capturing(&program);
        assert!(
            output.contains("42"),
            "async fn should execute sequentially in interpreter, got: {output}"
        );
    }

    #[test]
    fn async_runtime_e2e_compile() {
        // End-to-end: compile an async .tl program and verify the IR + stub are correct
        let source = r#"
            async fn fetch_data() -> i64 {
                42
            }
            fn main() {
                let result = fetch_data()
                print(result)
            }
        "#;
        let ir = compile_to_ir(source);

        // Should have all the async plumbing
        assert!(
            ir.contains("@tallow.fetch_data.body"),
            "should have body function"
        );
        assert!(ir.contains("@tallow_async_spawn"), "should have spawn call");
        assert!(
            ir.contains("@tallow_async_runtime_init"),
            "should have runtime init"
        );
        assert!(
            ir.contains("@tallow_async_runtime_shutdown"),
            "should have runtime shutdown"
        );

        // The stub source should be self-contained
        let stub = CodeGen::async_stub_source();
        assert!(!stub.is_empty(), "stub should not be empty");
    }

    // ── Monomorphization & Trait Codegen Tests ────────────────────────

    #[test]
    fn monomorphize_identity_i32() {
        let ir = compile_to_ir(
            r#"
            fn identity<T>(x: T) -> T { x }
            fn main() {
                let a = identity(42)
            }
        "#,
        );
        // Should emit a monomorphized version: tallow.identity.i64 (i32 lit infers to i64)
        assert!(
            ir.contains("@tallow.identity.i64"),
            "should have monomorphized identity.i64, IR:\n{ir}"
        );
        assert!(ir.contains("@tallow.main"), "should have main function");
    }

    #[test]
    fn monomorphize_identity_string() {
        let ir = compile_to_ir(
            r#"
            fn identity<T>(x: T) -> T { x }
            fn main() {
                let a = identity("hello")
            }
        "#,
        );
        // Should emit a monomorphized version: tallow.identity.String
        assert!(
            ir.contains("@tallow.identity.String"),
            "should have monomorphized identity.String, IR:\n{ir}"
        );
    }

    #[test]
    fn monomorphize_two_specializations() {
        let ir = compile_to_ir(
            r#"
            fn identity<T>(x: T) -> T { x }
            fn main() {
                let a = identity(42)
                let b = identity("world")
            }
        "#,
        );
        // Should have TWO monomorphized versions
        assert!(
            ir.contains("@tallow.identity.i64"),
            "should have identity.i64"
        );
        assert!(
            ir.contains("@tallow.identity.String"),
            "should have identity.String"
        );
    }

    #[test]
    fn generic_codegen_trait_method_static_dispatch() {
        let ir = compile_to_ir(
            r#"
            struct Point { x: i32, y: i32 }
            trait Describe {
                fn describe(self) -> String
            }
            impl Describe for Point {
                fn describe(self) -> String { "a point" }
            }
            fn main() {
                let p = Point { x: 10, y: 20 }
                let desc = p.describe()
            }
        "#,
        );
        // Trait method should be compiled as Point::describe (static dispatch)
        assert!(
            ir.contains("tallow.Point..describe") || ir.contains("\"tallow.Point::describe\""),
            "should have Point::describe method in IR, IR:\n{ir}"
        );
    }

