    // ── Enum Data Variant Tests ──────────────────────────────────────────

    #[test]
    fn codegen_enum_data_variant_construction() {
        // Enum with data variant should allocate a tagged struct with malloc,
        // store discriminant at offset 0, and payload at offset 1
        let ir = compile_to_ir(
            r#"
            enum Status {
                Active,
                Inactive,
                Pending(reason: String)
            }
            fn main() {
                let s = Status.Pending("review")
                print("done")
            }
        "#,
        );
        // Must allocate memory for the tagged struct (malloc)
        // The struct has: { i64 discriminant, i64 payload }
        // Pending is variant index 2
        assert!(
            ir.contains("call ptr @malloc"),
            "should malloc for data variant, IR:\n{ir}"
        );
        // Store discriminant 2 at base ptr
        assert!(
            ir.contains("store i64 2, ptr"),
            "should store discriminant 2 for Pending, IR:\n{ir}"
        );
        // Store payload at offset 1 via GEP
        assert!(
            ir.contains("getelementptr i64, ptr"),
            "should GEP for payload field, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_enum_data_variant_match_extract() {
        // Match on enum data variant should extract payload into binding
        let ir = compile_to_ir(
            r#"
            enum Status {
                Active,
                Inactive,
                Pending(reason: String)
            }
            fn main() {
                let s = Status.Pending("review")
                match s {
                    Active -> print("active")
                    Inactive -> print("inactive")
                    Pending(reason) -> print(reason)
                }
            }
        "#,
        );
        // Switch on discriminant loaded from the tagged struct ptr
        assert!(
            ir.contains("switch i64"),
            "should switch on discriminant, IR:\n{ir}"
        );
        // Should load discriminant from ptr (GEP offset 0 + load)
        assert!(
            ir.contains("load i64, ptr"),
            "should load discriminant from tagged struct, IR:\n{ir}"
        );
        // Pending arm should extract payload via GEP at offset 1
        // and use inttoptr to recover string ptr
        assert!(
            ir.contains("inttoptr i64"),
            "should inttoptr payload for string binding, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_enum_data_variant_no_data_backward_compat() {
        // Enums without ANY data variants should NOT use malloc -- bare i64 discriminants
        let ir = compile_to_ir(
            r#"
            enum Color {
                Red,
                Green,
                Blue
            }
            fn main() {
                let c = Color.Red
                print("done")
            }
        "#,
        );
        // Color.Red should be a simple constant 0, no malloc needed
        let main_section = ir.split("@tallow.main").nth(1).unwrap_or(&ir);
        // No malloc in main for discriminant-only enums
        assert!(
            !main_section.contains("call ptr @malloc"),
            "should NOT malloc for discriminant-only enum, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_enum_data_mixed_variants() {
        // Enum with both data and non-data variants -- all use tagged struct
        let ir = compile_to_ir(
            r#"
            enum Status {
                Active,
                Pending(reason: String)
            }
            fn main() {
                let a = Status.Active
                let p = Status.Pending("waiting")
                print("done")
            }
        "#,
        );
        // Both should use malloc because enum HAS data variants
        assert!(
            ir.contains("store i64 0, ptr"),
            "should store discriminant 0 for Active, IR:\n{ir}"
        );
        assert!(
            ir.contains("store i64 1, ptr"),
            "should store discriminant 1 for Pending, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_enum_data_variant_if_let() {
        // if-let with enum data variant should check discriminant and extract payload
        let ir = compile_to_ir(
            r#"
            enum Status {
                Active,
                Pending(reason: String)
            }
            fn main() {
                let s = Status.Pending("review")
                if let Pending(reason) = s {
                    print(reason)
                }
            }
        "#,
        );
        // Should check discriminant with icmp eq
        assert!(
            ir.contains("icmp eq i64"),
            "should compare discriminant, IR:\n{ir}"
        );
        // Should extract payload via GEP offset 1
        assert!(
            ir.contains("getelementptr i64, ptr"),
            "should GEP for payload in if-let, IR:\n{ir}"
        );
    }

