    #[test]
    fn codegen_import_local_file() {
        // Test import resolution: write helper file to temp dir, compile main that imports it
        use std::io::Write;
        let dir = tempfile::tempdir().expect("temp dir");
        let helper_path = dir.path().join("helper.tl");
        let mut f = std::fs::File::create(&helper_path).unwrap();
        writeln!(f, "fn helper() -> i64 {{ 42 }}").unwrap();
        drop(f);

        let main_src = "import helper\nfn main() {\n    let x = helper()\n    print(x)\n}\n";
        let (tokens, errors) = crate::lexer::tokenize(main_src);
        assert!(errors.is_empty(), "lex errors: {errors:?}");
        let program = crate::parser::Parser::parse(tokens).expect("parse error");
        let (env, _) = crate::typeck::TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        cg.set_source_dir(dir.path().display().to_string());
        let ir = cg.emit_module().expect("codegen error");
        assert!(
            ir.contains("@tallow.helper"),
            "imported helper function should be emitted, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_import_struct_from_file() {
        use std::io::Write;
        let dir = tempfile::tempdir().expect("temp dir");
        let helper_path = dir.path().join("types.tl");
        let mut f = std::fs::File::create(&helper_path).unwrap();
        writeln!(f, "struct Point {{\n    x: i64,\n    y: i64\n}}").unwrap();
        drop(f);

        let main_src =
            "import types\nfn main() {\n    let p = Point { x: 1, y: 2 }\n    print(p.x)\n}\n";
        let (tokens, errors) = crate::lexer::tokenize(main_src);
        assert!(errors.is_empty());
        let program = crate::parser::Parser::parse(tokens).expect("parse error");
        let (env, _) = crate::typeck::TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        cg.set_source_dir(dir.path().display().to_string());
        let ir = cg.emit_module().expect("codegen error");
        assert!(
            ir.contains("%struct.Point"),
            "imported struct should be emitted, IR:\n{ir}"
        );
    }

    #[test]
    fn codegen_import_circular_no_infinite_loop() {
        // Two files that import each other should not infinite loop
        use std::io::Write;
        let dir = tempfile::tempdir().expect("temp dir");
        let a_path = dir.path().join("mod_a.tl");
        let b_path = dir.path().join("mod_b.tl");
        let mut fa = std::fs::File::create(&a_path).unwrap();
        writeln!(fa, "import mod_b\nfn func_a() -> i64 {{ 1 }}").unwrap();
        drop(fa);
        let mut fb = std::fs::File::create(&b_path).unwrap();
        writeln!(fb, "import mod_a\nfn func_b() -> i64 {{ 2 }}").unwrap();
        drop(fb);

        let main_src = "import mod_a\nfn main() {\n    let x = func_a()\n    print(x)\n}\n";
        let (tokens, errors) = crate::lexer::tokenize(main_src);
        assert!(errors.is_empty());
        let program = crate::parser::Parser::parse(tokens).expect("parse error");
        let (env, _) = crate::typeck::TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        cg.set_source_dir(dir.path().display().to_string());
        // Should not infinite loop — visited set prevents re-parsing
        let ir = cg.emit_module().expect("codegen error");
        assert!(ir.contains("@tallow.func_a"), "func_a should be emitted");
    }

