    // ── Regex (shared engine) + Compress zlib Tests ────────────────────────

    #[test]
    fn codegen_stdlib_regex_matches_shared_engine() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let m = regex.matches("[0-9]+", "abc123def")
                if m { print("matched") }
            }
        "#,
        );
        // t_7a8efe20: the native arm calls the shared engine helper (the
        // interpreter's dispatch). The POSIX regcomp/regexec/regfree/malloc
        // sequence this test used to pin is gone by design.
        assert!(
            ir.contains("call i32 @tallow_regex_is_match("),
            "regex.matches should call tallow_regex_is_match FFI"
        );
        assert!(
            !ir.contains("@regcomp") && !ir.contains("@regexec") && !ir.contains("@regfree"),
            "regex.matches must not emit the POSIX regex path"
        );
    }

    #[test]
    fn codegen_stdlib_regex_replace_shared_engine() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                let result = regex.replace("[0-9]+", "abc123def", "NUM")
                print(result)
            }
        "#,
        );
        assert!(
            ir.contains("call ptr @tallow_regex_replace("),
            "regex.replace should call tallow_regex_replace FFI"
        );
        assert!(
            !ir.contains("@regcomp") && !ir.contains("@regexec") && !ir.contains("@regfree"),
            "regex.replace must not emit the POSIX regex path"
        );
    }

