    #[test]
    fn codegen_self_host_compiles() {
        // Verify self_host.tl (1256-line Tallow subset compiler) generates valid LLVM IR
        // without panicking. This is the end-to-end stress test for the codegen pipeline.
        let source = std::fs::read_to_string("examples/self_host.tl").unwrap_or_default();
        if source.is_empty() {
            return;
        } // skip if file not found

        let (tokens, errors) = lexer::tokenize(&source);
        assert!(errors.is_empty(), "self_host.tl lex errors: {errors:?}");
        let program = parser::Parser::parse(tokens).expect("self_host.tl parse error");
        let (env, _) = TypeChecker::new(&program).check();
        let mut cg = CodeGen::new(&program, &env);
        let ir = cg.emit_module().expect("self_host.tl codegen error");

        // Verify IR has expected structure for a 1256-line program
        assert!(
            ir.contains("define void @tallow.main()"),
            "should have main function"
        );
        assert!(
            ir.contains("@tallow.compile"),
            "should have compile function"
        );
        assert!(
            ir.contains("@tallow.is_digit"),
            "should have is_digit function"
        );
        assert!(
            ir.contains("@tallow.is_alpha"),
            "should have is_alpha function"
        );
        assert!(ir.contains("@tallow.ch"), "should have ch helper function");
        // Verify the IR is substantial (1256 lines of Tallow should produce significant IR)
        assert!(
            ir.len() > 10000,
            "IR should be substantial for 1256-line program, got {} bytes",
            ir.len()
        );
    }

    // ── Constant-time codegen tests (Phase 35-03) ───────────────────────────

    #[test]
    fn test_ct_function_has_optnone() {
        let ir = compile_to_ir(
            r#"
            @constant_time
            fn ct_add(a: i64, b: i64) -> i64 {
                a + b
            }
            fn main() {
                let x = ct_add(1, 2)
                print(x)
            }
        "#,
        );
        // CT function should use attribute group #1 (optnone noinline)
        assert!(
            ir.contains("#1"),
            "CT function should reference attribute group #1"
        );
        assert!(
            ir.contains("optnone"),
            "CT attribute group should contain optnone"
        );
        assert!(
            ir.contains("noinline"),
            "CT attribute group should contain noinline"
        );
        // Verify the CT function define uses #1
        assert!(
            ir.contains("@tallow.ct_add(i64 %param.a, i64 %param.b) #1"),
            "CT function define should use #1 attribute group"
        );
    }

    #[test]
    fn test_non_ct_function_no_optnone_on_define() {
        let ir = compile_to_ir(
            r#"
            fn normal_add(a: i64, b: i64) -> i64 {
                a + b
            }
            fn main() {
                let x = normal_add(1, 2)
                print(x)
            }
        "#,
        );
        // Normal function should use #0, not #1
        assert!(
            ir.contains("@tallow.normal_add(i64 %param.a, i64 %param.b) #0"),
            "non-CT function should use #0 attribute group"
        );
        // Should NOT have the optnone attribute group at all
        assert!(
            !ir.contains("attributes #1"),
            "no CT functions means no #1 attribute group should be emitted"
        );
    }

