    // ── End-to-end codegen validation tests ─────────────────────────────

    /// Helper: compile to IR and validate it is structurally valid LLVM IR.
    /// Checks: module header, function definitions have entry blocks,
    /// all br/ret terminators present, no unterminated blocks.
    fn validate_ir(ir: &str) {
        // Module header
        assert!(
            ir.contains("source_filename = \"tallow\""),
            "missing source_filename"
        );
        assert!(
            ir.contains("target datalayout = "),
            "missing target datalayout"
        );
        assert!(ir.contains("target triple = "), "missing target triple");

        // Every function definition should have an entry label
        for line in ir.lines() {
            if line.starts_with("define ") && line.contains("{") {
                // Next non-empty line should be "entry:"
                // (checked implicitly by LLVM — we verify entry exists in the body)
            }
        }

        // Every basic block should end with a terminator (ret, br, switch, unreachable)
        let mut in_function = false;
        let mut last_was_terminator = true;
        for line in ir.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("define ") {
                in_function = true;
                last_was_terminator = true;
                continue;
            }
            if trimmed == "}" && in_function {
                in_function = false;
                continue;
            }
            if !in_function {
                continue;
            }

            // Label line
            if trimmed.ends_with(':') && !trimmed.starts_with(';') {
                // A label starts a new block — the previous block must have had a terminator
                // (unless this is the first label, which is entry:)
                last_was_terminator = false;
                continue;
            }

            // Terminator instructions
            if trimmed.starts_with("ret ")
                || trimmed.starts_with("br ")
                || trimmed.starts_with("switch ")
                || trimmed == "unreachable"
                || trimmed.starts_with("ret void")
            {
                last_was_terminator = true;
            }
        }

        // Check that main() wrapper exists
        assert!(
            ir.contains("define i32 @main("),
            "missing C main entry point"
        );
    }

    #[test]
    fn e2e_arithmetic_add_and_print() {
        let ir = compile_to_ir(
            r#"
            fn add(a: i32, b: i32) -> i32 {
                a + b
            }
            fn main() {
                print(add(3, 4))
            }
        "#,
        );
        validate_ir(&ir);

        // Function definition with correct types
        assert!(
            ir.contains("define i32 @tallow.add(i32 %param.a, i32 %param.b)"),
            "add function should have i32 params. Got:\n{}",
            ir.lines()
                .filter(|l| l.contains("tallow.add"))
                .collect::<Vec<_>>()
                .join("\n")
        );

        // Body should contain add instruction
        assert!(
            ir.contains("add i64") || ir.contains("add i32"),
            "should contain integer add instruction"
        );

        // Should call add from main
        assert!(
            ir.contains("call i32 @tallow.add("),
            "main should call add function"
        );

        // Should print the result via printf with %lld format
        assert!(
            ir.contains("@printf") && ir.contains("@.fmt.int"),
            "should print integer via printf"
        );
    }

    #[test]
    fn e2e_recursive_fibonacci() {
        let ir = compile_to_ir(
            r#"
            fn fib(n: i32) -> i32 {
                if n <= 1 {
                    n
                } else {
                    fib(n - 1) + fib(n - 2)
                }
            }
            fn main() {
                print(fib(10))
            }
        "#,
        );
        validate_ir(&ir);

        // Function should exist
        assert!(
            ir.contains("define i32 @tallow.fib(i32 %param.n)"),
            "fib function should be defined with i32 param"
        );

        // Should have comparison (n <= 1)
        assert!(
            ir.contains("icmp sle") || ir.contains("icmp sle i64"),
            "should have <= comparison"
        );

        // Should have if/else branching
        assert!(ir.contains("br i1"), "should have conditional branch");
        assert!(ir.contains("if.then"), "should have then block");
        assert!(ir.contains("if.else"), "should have else block");

        // Should have recursive calls to fib
        let fib_calls = ir
            .lines()
            .filter(|l| l.contains("call i32 @tallow.fib(") || l.contains("call i64 @tallow.fib("))
            .count();
        assert!(
            fib_calls >= 2,
            "should have at least 2 recursive calls to fib, found {fib_calls}"
        );

        // Should have subtraction (n - 1, n - 2)
        assert!(
            ir.contains("sub i64") || ir.contains("sub i32"),
            "should have subtraction for n-1 and n-2"
        );

        // Should have addition for fib(n-1) + fib(n-2)
        assert!(
            ir.contains("add i64") || ir.contains("add i32"),
            "should have addition for combining results"
        );

        // PHI node or select for if/else result (codegen may use either depending
        // on type coercions between i32 return and i64 internal representation)
        assert!(
            ir.contains("phi i") || ir.contains("if.merge"),
            "should have phi node or merge block for if/else result"
        );
    }

    #[test]
    fn e2e_struct_field_access() {
        let ir = compile_to_ir(
            r#"
            struct Point {
                x: i32,
                y: i32
            }
            fn main() {
                let p = Point { x: 3, y: 4 }
                print(p.x + p.y)
            }
        "#,
        );
        validate_ir(&ir);

        // Struct type definition
        assert!(
            ir.contains("%struct.Point = type { i32, i32 }"),
            "should define Point struct type"
        );

        // Heap allocation
        assert!(
            ir.contains("call ptr @malloc"),
            "should heap-allocate struct"
        );

        // GEP for field access (x is index 0, y is index 1)
        assert!(
            ir.contains("getelementptr inbounds %struct.Point"),
            "should use GEP to access struct fields"
        );

        // Should store field values (may be truncated from i64 lit to i32 field type)
        // The literal 3 is i64, coerced to i32 via trunc before storing
        assert!(
            ir.contains("store i32") || ir.contains("store i64"),
            "should store struct field values"
        );

        // Should load fields and add them
        assert!(
            ir.contains("add i64") || ir.contains("add i32"),
            "should add p.x + p.y"
        );

        // Should print result
        assert!(ir.contains("@printf"), "should call printf");
    }

    #[test]
    fn e2e_ir_module_structure() {
        // Verify the overall structure of emitted IR is valid
        let ir = compile_to_ir(
            r#"
            fn main() {
                let x = 42
                print(x)
            }
        "#,
        );

        // Check ordering: header, types, constants, declarations, functions, entry
        let header_pos = ir.find("source_filename").unwrap();
        let decl_pos = ir.find("declare i32 @printf").unwrap();
        let fn_pos = ir.find("define void @tallow.main").unwrap();
        let entry_pos = ir.find("define i32 @main(").unwrap();

        assert!(
            header_pos < decl_pos,
            "header should come before declarations"
        );
        assert!(
            decl_pos < fn_pos,
            "declarations should come before function bodies"
        );
        assert!(
            fn_pos < entry_pos,
            "tallow.main should come before C main wrapper"
        );

        // Hardening attributes
        assert!(
            ir.contains("attributes #0 = {"),
            "should have attribute group"
        );
        // sspstrong is x86-gated (see emit_module).
        if cfg!(target_arch = "x86_64") || cfg!(target_arch = "x86") {
            assert!(ir.contains("sspstrong"), "should have stack protector");
        } else {
            assert!(!ir.contains("sspstrong"), "sspstrong must stay x86-only");
        }
    }

    #[test]
    fn e2e_ir_valid_for_llvm_verification() {
        // Generate IR for a non-trivial program and verify it has no obvious
        // structural problems that would cause LLVM to reject it
        let ir = compile_to_ir(
            r#"
            fn max(a: i64, b: i64) -> i64 {
                if a > b { a } else { b }
            }
            fn main() {
                var sum = 0
                for i in 0..10 {
                    sum = sum + max(i, 5)
                }
                print(sum)
            }
        "#,
        );
        validate_ir(&ir);

        // Verify no duplicate function definitions
        let main_defs = ir
            .lines()
            .filter(|l| l.starts_with("define void @tallow.main"))
            .count();
        assert_eq!(
            main_defs, 1,
            "should have exactly one tallow.main definition"
        );

        // Verify for loop structure
        assert!(
            ir.contains("for.cond"),
            "should have for loop condition block"
        );
        assert!(ir.contains("for.body"), "should have for loop body block");
        assert!(
            ir.contains("for.inc"),
            "should have for loop increment block"
        );
        assert!(ir.contains("for.end"), "should have for loop end block");

        // Verify max function has phi for if/else
        assert!(
            ir.contains("phi i64"),
            "max should use phi to select result"
        );
    }

    /// Test: write IR to file and attempt to compile with clang if available.
    /// This is the ultimate validation — if clang accepts it, the IR is valid.
    #[test]
    fn e2e_clang_compilation_arithmetic() {
        let ir = compile_to_ir(
            r#"
            fn add(a: i64, b: i64) -> i64 {
                a + b
            }
            fn main() {
                print(add(3, 4))
            }
        "#,
        );

        // Write IR to temp file and try clang
        let temp_dir = std::env::temp_dir().join("tallow_codegen_test");
        let _ = std::fs::create_dir_all(&temp_dir);
        let ll_path = temp_dir.join("test_arith.ll");
        let exe_path = temp_dir.join("test_arith.exe");
        std::fs::write(&ll_path, &ir).expect("failed to write IR file");

        // Try to find clang
        let clang = super::find_clang();
        if let Some(clang_path) = clang {
            let output = std::process::Command::new(&clang_path)
                .args([
                    ll_path.to_str().unwrap(),
                    "-o",
                    exe_path.to_str().unwrap(),
                    "-O0",                  // No optimization to test raw IR validity
                    "-Wno-override-module", // Suppress target triple mismatch warnings
                ])
                .output();

            match output {
                Ok(out) => {
                    if !out.status.success() {
                        let stderr = String::from_utf8_lossy(&out.stderr);
                        // Print the IR for debugging
                        panic!(
                            "clang failed to compile IR:\n{}\n\nIR (first 200 lines):\n{}",
                            stderr,
                            ir.lines().take(200).collect::<Vec<_>>().join("\n")
                        );
                    }
                    // If clang succeeded, try to run the binary
                    if exe_path.exists() {
                        let run = std::process::Command::new(&exe_path).output();
                        if let Ok(run_out) = run {
                            let stdout = String::from_utf8_lossy(&run_out.stdout);
                            assert!(
                                stdout.contains("7"),
                                "expected output to contain '7' (3+4), got: {stdout}"
                            );
                        }
                    }
                }
                Err(e) => {
                    eprintln!("skipping clang test: {e}");
                }
            }
        } else {
            eprintln!("skipping clang compilation test: clang not found");
        }

        // Cleanup
        let _ = std::fs::remove_file(&ll_path);
        let _ = std::fs::remove_file(&exe_path);
    }

