    // ── F3: compiled `panic` / `assert` must fail loud ─────────────────────
    //
    // Before the fix, both names fell through `emit_call`'s unknown-function
    // fallback and compiled to a bare `0`: `fn main() { panic("boom") }`
    // built fine, printed nothing and exited 0 (verified on the pre-fix
    // binary). The interpreter always raised `runtime error: panic: <msg>`
    // with rc=1; the assertions below pin the compiled path to that contract.

    #[test]
    fn f3_panic_compiled_fails_loud_ir() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                panic("boom")
            }
        "#,
        );
        assert!(
            ir.contains("runtime error: panic: "),
            "compiled panic must print the interpreter-shaped fatal prefix"
        );
        assert!(
            ir.contains("@.str."),
            "the panic message must be interned as a string constant"
        );
        assert!(ir.contains("boom"), "compiled panic must carry its message");
        assert!(
            ir.contains("call void @exit(i32 1)"),
            "compiled panic must exit non-zero (used to be a silent 0)"
        );
        assert!(
            ir.contains("after.panic"),
            "panic must terminate a block and re-open a continuation label"
        );
    }

    #[test]
    fn f3_assert_compiled_fails_loud_ir() {
        let ir = compile_to_ir(
            r#"
            fn main() {
                assert(false, "boom-assert")
            }
        "#,
        );
        assert!(ir.contains("br i1"), "assert must branch on the condition");
        assert!(
            ir.contains("assert.fail"),
            "assert must have a failure block"
        );
        assert!(
            ir.contains("runtime error: assertion failed: "),
            "compiled assert must print the interpreter-shaped fatal prefix"
        );
        assert!(ir.contains("boom-assert"), "assert must carry its message");
        assert!(
            ir.contains("call void @exit(i32 1)"),
            "failed assert must exit non-zero"
        );
    }

    /// Compile `panic`/`assert` fixtures with clang, execute the result and
    /// check the real process contract: non-zero rc and the message present.
    #[test]
    fn f3_compiled_panic_and_assert_run_fail_loud() {
        let cases = [
            ("f3_panic", "fn main() {\n    panic(\"boom-e2e\")\n}\n", "boom-e2e"),
            (
                "f3_assert",
                "fn main() {\n    assert(false, \"boom-assert-e2e\")\n}\n",
                "boom-assert-e2e",
            ),
        ];

        let temp_dir = std::env::temp_dir().join("tallow_codegen_f3");
        let _ = std::fs::create_dir_all(&temp_dir);

        let Some(clang_path) = super::find_clang() else {
            eprintln!("skipping clang test: clang not found");
            return;
        };

        for (name, source, needle) in cases {
            let ir = compile_to_ir(source);
            let ll_path = temp_dir.join(format!("{name}.ll"));
            let exe_path = temp_dir.join(format!("{name}.bin"));
            std::fs::write(&ll_path, &ir).expect("failed to write IR file");

            let out = std::process::Command::new(&clang_path)
                .args([
                    ll_path.to_str().unwrap(),
                    "-o",
                    exe_path.to_str().unwrap(),
                    "-O0",
                    "-Wno-override-module",
                ])
                .output()
                .expect("failed to invoke clang");
            assert!(
                out.status.success(),
                "clang rejected {name} IR:\n{}",
                String::from_utf8_lossy(&out.stderr)
            );

            let run_out = std::process::Command::new(&exe_path)
                .output()
                .expect("failed to run compiled fixture");
            assert!(
                !run_out.status.success(),
                "{name}: compiled run must not exit 0 (silent no-op was F3)"
            );
            assert_eq!(
                run_out.status.code(),
                Some(1),
                "{name}: expected the interpreter's rc=1 contract"
            );
            let combined = format!(
                "{}{}",
                String::from_utf8_lossy(&run_out.stdout),
                String::from_utf8_lossy(&run_out.stderr)
            );
            assert!(
                combined.contains(needle),
                "{name}: message `{needle}` missing from output: {combined:?}"
            );

            let _ = std::fs::remove_file(&ll_path);
            let _ = std::fs::remove_file(&exe_path);
        }
    }

    // ── F1: shipped example must pass clang-18 native codegen ──────────────
    //
    // `examples/public_source_get_batch.tl` failed native codegen on clang
    // 18.1.3, 11/11 runs: the IR emitter allocated `%21` for an `alloca ptr`
    // right after the `http.batch` stub's *unassigned* `call i32 @printf`.
    // An unassigned non-void call still consumes an unnamed value number in
    // clang's parser, so every later explicit `%N` was one behind:
    //   error: instruction expected to be numbered '%22' or greater
    // `tallow run` then fell back to the interpreter silently. This test
    // compiles the shipped example's IR with clang and fails if the emitter
    // ever desynchronizes the numbering again.
    #[test]
    fn f1_example_public_source_get_batch_compiles_with_clang() {
        let ir = compile_to_ir(include_str!("../examples/public_source_get_batch.tl"));
        assert!(ir.contains("@tallow.main"), "example must produce IR");

        // The root cause, stated as an invariant per function: a function that
        // uses *numbered* temporaries (`%N = …`) must not contain an unassigned
        // result-producing instruction. clang's parser hands such an instruction
        // the next unnamed number, so every later explicit `%N` is one behind
        // and clang rejects the module. Hand-written prelude helpers use named
        // values only, so they have no numbered space to desynchronize.
        let result_ops = [
            "call", "load", "getelementptr", "icmp", "fcmp", "select", "add", "sub", "mul",
            "sdiv", "srem", "and", "or", "xor", "shl", "lshr", "ashr", "fadd", "fsub", "fmul",
            "fdiv", "zext", "sext", "trunc", "bitcast", "ptrtoint", "inttoptr", "sitofp",
            "fptosi", "phi",
        ];
        let mut cur: Vec<&str> = Vec::new();
        let mut bodies: Vec<Vec<&str>> = Vec::new();
        for line in ir.lines() {
            if line.starts_with("define ") && !cur.is_empty() {
                bodies.push(std::mem::take(&mut cur));
            }
            cur.push(line);
        }
        if !cur.is_empty() {
            bodies.push(cur);
        }
        for body in bodies {
            let uses_numbers = body.iter().any(|l| {
                let t = l.trim_start();
                let mut cs = t.chars();
                cs.next() == Some('%')
                    && cs.next().map_or(false, |d| d.is_ascii_digit())
                    && t.contains(" = ")
            });
            if !uses_numbers {
                continue;
            }
            for line in &body {
                let t = line.trim_start();
                let mut words = t.split_whitespace();
                let op = words.next().unwrap_or("");
                if !result_ops.contains(&op) || t.contains(" = ") {
                    continue;
                }
                if op == "call" && words.next() == Some("void") {
                    continue; // void calls do not consume an unnamed number
                }
                panic!(
                    "unassigned result-producing `{op}` inside a numbered function \
                     desyncs clang's implicit numbering: {line}"
                );
            }
        }

        let temp_dir = std::env::temp_dir().join("tallow_codegen_f1");
        let _ = std::fs::create_dir_all(&temp_dir);
        let ll_path = temp_dir.join("public_source_get_batch.ll");
        let obj_path = temp_dir.join("public_source_get_batch.o");
        std::fs::write(&ll_path, &ir).expect("failed to write IR file");

        let Some(clang_path) = super::find_clang() else {
            eprintln!("skipping clang test: clang not found");
            return;
        };

        // `-c` runs the full LL parser (unlike `-fsyntax-only`, which skips the
        // SSA numbering check) without needing the runtime symbols to link.
        let out = std::process::Command::new(&clang_path)
            .args([
                ll_path.to_str().unwrap(),
                "-c",
                "-o",
                obj_path.to_str().unwrap(),
                "-O0",
                "-Wno-override-module",
            ])
            .output()
            .expect("failed to invoke clang");
        assert!(
            out.status.success(),
            "clang rejected the shipped example IR (F1 regression):\n{}",
            String::from_utf8_lossy(&out.stderr)
        );

        let _ = std::fs::remove_file(&ll_path);
        let _ = std::fs::remove_file(&obj_path);
    }

    // ── F1b: i32 values must be extended before an i64 printf slot ─────────

    /// Pre-fix, `print(add(10, 20))` for `fn add(a: i32, b: i32) -> i32`
    /// emitted `%9 = call i32 (ptr, ...) @printf(ptr @.fmt.int, i64 %8)` with
    /// `%8 = load i32` — clang rejected the module
    /// (`'%8' defined with type 'i32' but expected 'i64'`) and `tallow run`
    /// silently interpreted the program.
    #[test]
    fn f1b_i32_print_compiles_and_runs() {
        let ir = compile_to_ir(
            r#"
            fn add(a: i32, b: i32) -> i32 {
                a + b
            }
            fn main() {
                let s = add(10, 20)
                print(s)
            }
        "#,
        );
        assert!(
            ir.contains("sext i32"),
            "an i32 value must be sign-extended before the i64 printf slot"
        );

        let temp_dir = std::env::temp_dir().join("tallow_codegen_f1b");
        let _ = std::fs::create_dir_all(&temp_dir);
        let ll_path = temp_dir.join("i32_print.ll");
        let exe_path = temp_dir.join("i32_print.bin");
        std::fs::write(&ll_path, &ir).expect("failed to write IR file");

        let Some(clang_path) = super::find_clang() else {
            eprintln!("skipping clang test: clang not found");
            return;
        };

        let out = std::process::Command::new(&clang_path)
            .args([
                ll_path.to_str().unwrap(),
                "-o",
                exe_path.to_str().unwrap(),
                "-O0",
                "-Wno-override-module",
            ])
            .output()
            .expect("failed to invoke clang");
        assert!(
            out.status.success(),
            "clang rejected the i32-print IR (F1b regression):\n{}",
            String::from_utf8_lossy(&out.stderr)
        );

        let run_out = std::process::Command::new(&exe_path)
            .output()
            .expect("failed to run compiled fixture");
        assert_eq!(run_out.status.code(), Some(0), "compiled run must succeed");
        let stdout = String::from_utf8_lossy(&run_out.stdout);
        assert!(
            stdout.contains("30"),
            "expected add(10, 20) = 30, got: {stdout:?}"
        );

        let _ = std::fs::remove_file(&ll_path);
        let _ = std::fs::remove_file(&exe_path);
    }

    // ── F3 follow-up: compiled assert_eq / assert_ne must fail loud ────────

    /// Pre-fix these two names took the same silent-`0` fallback as `panic`,
    /// so a *failing* `assert_eq`/`assert_ne` exited 0. Contract pinned here:
    /// failing comparisons exit 1 with the interpreter's message (explicit and
    /// default form); passing comparisons exit 0 and continue.
    #[test]
    fn f3_assert_eq_ne_compiled_run_fail_loud() {
        // (name, source, expect_fail, needle)
        let cases: [(&str, &str, bool, &str); 6] = [
            (
                "aeq_fail_msg",
                "fn main() {\n    assert_eq(1, 2, \"eq-nope\")\n}\n",
                true,
                "eq-nope",
            ),
            (
                "aeq_fail_default",
                "fn main() {\n    assert_eq(\"a\", \"b\")\n}\n",
                true,
                "expected `a` == `b`",
            ),
            (
                "aeq_pass",
                "fn main() {\n    assert_eq(7, 7, \"never\")\n    print(\"eq-ok\")\n}\n",
                false,
                "eq-ok",
            ),
            (
                "ane_fail_msg",
                "fn main() {\n    assert_ne(5, 5, \"ne-nope\")\n}\n",
                true,
                "ne-nope",
            ),
            (
                "ane_fail_default",
                "fn main() {\n    assert_ne(\"a\", \"a\")\n}\n",
                true,
                "expected `a` != `a`",
            ),
            (
                "ane_pass",
                "fn main() {\n    assert_ne(5, 6, \"never\")\n    print(\"ne-ok\")\n}\n",
                false,
                "ne-ok",
            ),
        ];

        let temp_dir = std::env::temp_dir().join("tallow_codegen_f3_cmp");
        let _ = std::fs::create_dir_all(&temp_dir);

        let Some(clang_path) = super::find_clang() else {
            eprintln!("skipping clang test: clang not found");
            return;
        };

        for (name, source, expect_fail, needle) in cases {
            let ir = compile_to_ir(source);
            let ll_path = temp_dir.join(format!("{name}.ll"));
            let exe_path = temp_dir.join(format!("{name}.bin"));
            std::fs::write(&ll_path, &ir).expect("failed to write IR file");

            let out = std::process::Command::new(&clang_path)
                .args([
                    ll_path.to_str().unwrap(),
                    "-o",
                    exe_path.to_str().unwrap(),
                    "-O0",
                    "-Wno-override-module",
                ])
                .output()
                .expect("failed to invoke clang");
            assert!(
                out.status.success(),
                "clang rejected {name} IR:\n{}",
                String::from_utf8_lossy(&out.stderr)
            );

            let run_out = std::process::Command::new(&exe_path)
                .output()
                .expect("failed to run compiled fixture");
            let combined = format!(
                "{}{}",
                String::from_utf8_lossy(&run_out.stdout),
                String::from_utf8_lossy(&run_out.stderr)
            );

            if expect_fail {
                assert_eq!(
                    run_out.status.code(),
                    Some(1),
                    "{name}: failing comparison must exit 1 (silent no-op was the bug)"
                );
                assert!(
                    combined.contains(needle),
                    "{name}: message `{needle}` missing from output: {combined:?}"
                );
                assert!(
                    combined.contains("runtime error: assertion failed: "),
                    "{name}: interpreter-shaped fatal prefix missing: {combined:?}"
                );
            } else {
                assert_eq!(
                    run_out.status.code(),
                    Some(0),
                    "{name}: passing comparison must exit 0 (got: {combined:?})"
                );
                assert!(
                    combined.contains(needle),
                    "{name}: expected `{needle}` in output: {combined:?}"
                );
            }

            let _ = std::fs::remove_file(&ll_path);
            let _ = std::fs::remove_file(&exe_path);
        }
    }

