    // ── http.batch: native lowering (the stub path is retired for it) ──────

    /// Pre-lowering, `http.batch` reached `emit_stdlib_stub`: the compiled
    /// binary printed a stub warning and `.len` read the stub's error string.
    /// The lowering must call the runtime FFI for every batch.
    #[test]
    fn http_batch_lowers_to_runtime_ffi_not_the_stub() {
        let ir = compile_to_ir(
            r#"
            import tallow.http
            fn main() {
                let urls = ["http://127.0.0.1:9/a", "http://127.0.0.1:9/b"]
                let r = http.batch(urls, 2)
                print("len=" + r.len.to_string())
            }
        "#,
        );
        assert!(
            ir.contains("declare ptr @tallow_http_batch(ptr, i64)"),
            "the batch FFI must be declared in the prelude"
        );
        assert!(
            ir.contains("call ptr @tallow_http_batch(ptr"),
            "http.batch must lower to the runtime FFI"
        );
        assert!(
            !ir.contains("stub called in compiled mode"),
            "http.batch must not reach the stub path any more"
        );
        assert!(
            ir.contains("http.batch requires a [String] URLs argument"),
            "a null URLs argument must fail loud, not return a silent empty array"
        );
    }

